cat <<'EOF' > cmd/tparse/main.go
package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// ---------------- ANSI color helpers ----------------

var colorsEnabled = true

type color int

const (
	colorReset color = iota
	colorRed
	colorGreen
	colorYellow
	colorBlue
	colorMagenta
	colorCyan
	colorFg103 // 256-color box color
)

func c(s string, col color) string {
	if !colorsEnabled {
		return s
	}
	switch col {
	case colorRed:
		return "\x1b[91m" + s + "\x1b[0m"
	case colorGreen:
		return "\x1b[92m" + s + "\x1b[0m"
	case colorYellow:
		return "\x1b[93m" + s + "\x1b[0m"
	case colorBlue:
		return "\x1b[94m" + s + "\x1b[0m"
	case colorMagenta:
		return "\x1b[95m" + s + "\x1b[0m"
	case colorCyan:
		return "\x1b[96m" + s + "\x1b[0m"
	case colorFg103:
		return "\x1b[38;5;103m" + s + "\x1b[0m"
	}
	return s
}

// ---------------- Event struct ----------------

type Event struct {
	Time    time.Time
	Action  string
	Package string
	Test    string
	Elapsed float64
	Output  string
}

type Status int

const (
	StatusUnknown Status = iota
	StatusPass
	StatusFail
	StatusSkip
	StatusPanic
	StatusBuildFail
	StatusNoTest
)

func (s Status) String() string {
	switch s {
	case StatusPass:
		return "PASS"
	case StatusFail:
		return "FAIL"
	case StatusSkip:
		return "SKIP"
	case StatusPanic:
		return "PANIC"
	case StatusBuildFail:
		return "BUILD"
	case StatusNoTest:
		return "NOTEST"
	}
	return ""
}

// ---------------- Test & Package models ----------------

type Test struct {
	Name    string
	Package string
	Status  Status
	Elapsed float64
	Output  []string // captured output lines (verbatim with \n)
}

type Package struct {
	Name     string
	Status   Status
	Elapsed  float64
	Cover    string // e.g. "50.0%" or "" if not present
	NoTest   bool
	NoTestReason string // "[no test files]" or "[no tests to run]"
	HasPanic bool
	PanicTest string // test name where panic originated (if any)
	PackageOutput []string // package-level output (no Test)
	Tests    map[string]*Test
	TestOrder []string
}

func newPackage(name string) *Package {
	return &Package{
		Name:  name,
		Tests: map[string]*Test{},
	}
}

// ---------------- Ingest ----------------

var coverRe = regexp.MustCompile(`coverage:\s+([0-9.]+%)\s+of statements`)
var noTestFilesRe = regexp.MustCompile(`\[no test files\]`)
var noTestsToRunRe = regexp.MustCompile(`\[no tests to run\]`)

func ingest(r io.Reader, follow io.Writer, includeTime bool) (map[string]*Package, []string, error) {
	pkgs := map[string]*Package{}
	var order []string
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024*1024), 10*1024*1024)
	anyEvent := false
	for scanner.Scan() {
		line := scanner.Bytes()
		line = trimTrailingCR(line)
		if len(line) == 0 {
			continue
		}
		if line[0] != '{' {
			continue
		}
		var e Event
		if err := json.Unmarshal(line, &e); err != nil {
			continue
		}
		anyEvent = true
		if _, ok := pkgs[e.Package]; !ok && e.Package != "" {
			pkgs[e.Package] = newPackage(e.Package)
			order = append(order, e.Package)
		}
		pkg := pkgs[e.Package]

		switch e.Action {
		case "run":
			if e.Test != "" {
				t := &Test{Name: e.Test, Package: e.Package}
				pkg.Tests[e.Test] = t
				pkg.TestOrder = append(pkg.TestOrder, e.Test)
			}
		case "output":
			if follow != nil {
				if shouldFollow(e.Output) {
					if includeTime {
						fmt.Fprintf(follow, "%s %s", e.Time.Format(time.RFC3339Nano), e.Output)
					} else {
						fmt.Fprint(follow, e.Output)
					}
				}
			}
			if pkg == nil {
				continue
			}
			if e.Test != "" {
				t, ok := pkg.Tests[e.Test]
				if !ok {
					t = &Test{Name: e.Test, Package: e.Package}
					pkg.Tests[e.Test] = t
					pkg.TestOrder = append(pkg.TestOrder, e.Test)
				}
				t.Output = append(t.Output, e.Output)
			} else {
				pkg.PackageOutput = append(pkg.PackageOutput, e.Output)
				if m := coverRe.FindStringSubmatch(e.Output); m != nil {
					pkg.Cover = m[1]
				}
				if noTestFilesRe.MatchString(e.Output) {
					pkg.NoTest = true
					pkg.NoTestReason = "[no test files]"
				} else if noTestsToRunRe.MatchString(e.Output) {
					pkg.NoTest = true
					pkg.NoTestReason = "[no tests to run]"
				}
				// Detect package-level panics from test output
				if strings.HasPrefix(e.Output, "panic:") {
					pkg.HasPanic = true
				}
			}
		case "pass":
			if e.Test != "" {
				if t, ok := pkg.Tests[e.Test]; ok {
					t.Status = StatusPass
					t.Elapsed = e.Elapsed
				}
			} else {
				if pkg.Status == StatusUnknown {
					pkg.Status = StatusPass
				}
				pkg.Elapsed = e.Elapsed
			}
		case "fail":
			if e.Test != "" {
				if t, ok := pkg.Tests[e.Test]; ok {
					t.Status = StatusFail
					t.Elapsed = e.Elapsed
				}
			} else {
				pkg.Status = StatusFail
				pkg.Elapsed = e.Elapsed
			}
		case "skip":
			if e.Test != "" {
				if t, ok := pkg.Tests[e.Test]; ok {
					t.Status = StatusSkip
					t.Elapsed = e.Elapsed
				}
			} else {
				if pkg.Status == StatusUnknown {
					pkg.Status = StatusPass
				}
				pkg.Elapsed = e.Elapsed
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, nil, err
	}
	// Determine panic tests
	for _, p := range pkgs {
		for _, t := range p.Tests {
			for _, line := range t.Output {
				if strings.HasPrefix(line, "panic:") || strings.HasPrefix(strings.TrimSpace(line), "panic:") {
					p.HasPanic = true
					p.PanicTest = t.Name
					break
				}
			}
			if p.HasPanic {
				break
			}
		}
	}
	// Decide no-test status -> overrides
	for _, p := range pkgs {
		if p.NoTest {
			p.Status = StatusNoTest
		}
	}
	if !anyEvent {
		return nil, nil, errNoParsableEvents
	}
	return pkgs, order, nil
}

var errNoParsableEvents = errors.New("no parsable events: Make sure to run go test with -json flag")

func trimTrailingCR(b []byte) []byte {
	if len(b) > 0 && b[len(b)-1] == '\r' {
		return b[:len(b)-1]
	}
	return b
}

// Determine whether an output line should be shown in "follow" mode.
// tparse suppresses the standard noise lines.
func shouldFollow(s string) bool {
	trim := strings.TrimRight(s, "\n")
	if strings.HasPrefix(trim, "=== RUN") ||
		strings.HasPrefix(trim, "=== PAUSE") ||
		strings.HasPrefix(trim, "=== CONT") ||
		strings.HasPrefix(trim, "=== NAME") ||
		strings.HasPrefix(trim, "--- PASS") ||
		strings.HasPrefix(trim, "--- FAIL") ||
		strings.HasPrefix(trim, "--- SKIP") {
		return false
	}
	if trim == "PASS" || trim == "FAIL" || trim == "SKIP" {
		return false
	}
	return true
}

// ---------------- Rendering ----------------

type format int

const (
	formatBasic format = iota
	formatPlain
	formatMarkdown
)

type renderOpts struct {
	format      format
	showPass    bool
	showSkip    bool
	showAll     bool
	showNotest  bool
	smallScreen bool
	slow        int
	sortBy      string
	trimPath    string
	progress    bool
}

func render(pkgs map[string]*Package, order []string, w io.Writer, opts renderOpts) {
	// Sort packages by chosen criteria
	pkgList := make([]*Package, 0, len(pkgs))
	for _, n := range order {
		pkgList = append(pkgList, pkgs[n])
	}
	// default sort is name (preserves alphabetical order, not ingest order)
	switch opts.sortBy {
	case "elapsed":
		sort.SliceStable(pkgList, func(i, j int) bool {
			return pkgList[i].Elapsed > pkgList[j].Elapsed
		})
	case "cover":
		sort.SliceStable(pkgList, func(i, j int) bool {
			return coverVal(pkgList[i].Cover) > coverVal(pkgList[j].Cover)
		})
	default: // name
		sort.SliceStable(pkgList, func(i, j int) bool {
			return pkgList[i].Name < pkgList[j].Name
		})
	}

	// Progress header for each package
	if opts.progress {
		for _, p := range pkgList {
			if p.Status == StatusNoTest && !opts.showNotest {
				continue
			}
			printProgressLine(w, p)
		}
	}

	// Tests table
	var testRows [][]string
	for _, p := range pkgList {
		var add []*Test
		for _, t := range p.Tests {
			switch t.Status {
			case StatusPass:
				if opts.showAll || opts.showPass {
					add = append(add, t)
				}
			case StatusSkip:
				if opts.showAll || opts.showSkip {
					add = append(add, t)
				}
			case StatusFail:
				// always in summary? Actually failed tests are shown in failure section, not table
			}
		}
		// sort within package by elapsed desc
		sort.SliceStable(add, func(i, j int) bool {
			return add[i].Elapsed > add[j].Elapsed
		})
		// apply slow limit across all pkgs? We'll apply after collecting all
		for _, t := range add {
			testRows = append(testRows, []string{
				statusText(t.Status),
				fmt.Sprintf("%.2f", t.Elapsed),
				t.Name,
				t.Package,
			})
		}
		// Blank row separator between packages (we'll handle after collecting)
		if len(add) > 0 {
			testRows = append(testRows, nil) // signals separator
		}
	}
	// drop trailing separator
	for len(testRows) > 0 && testRows[len(testRows)-1] == nil {
		testRows = testRows[:len(testRows)-1]
	}
	if opts.slow > 0 && len(testRows) > 0 {
		// Flatten (remove separators) and take top N by elapsed
		flat := make([][]string, 0)
		for _, r := range testRows {
			if r != nil {
				flat = append(flat, r)
			}
		}
		sort.SliceStable(flat, func(i, j int) bool {
			ei, _ := strconv.ParseFloat(flat[i][1], 64)
			ej, _ := strconv.ParseFloat(flat[j][1], 64)
			return ei > ej
		})
		if len(flat) > opts.slow {
			flat = flat[:opts.slow]
		}
		testRows = flat
	}
	if len(testRows) > 0 {
		headers := []string{"Status", "Elapsed", "Test", "Package"}
		writeTable(w, headers, testRows, opts.format, true)
	}

	// Failure / panic sections
	for _, p := range pkgList {
		printFailures(w, p, opts)
	}

	// Summary table
	var rows [][]string
	for _, p := range pkgList {
		if p.Status == StatusNoTest && !hasAnyTests(p) {
			if !opts.showNotest && !opts.showAll && !opts.showPass && !opts.showSkip {
				// always show notest rows actually - the default shows them
			}
		}
		rows = append(rows, packageRow(p, opts))
	}
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	writeTable(w, headers, rows, opts.format, false)
}

func hasAnyTests(p *Package) bool {
	for _, t := range p.Tests {
		_ = t
		return true
	}
	return false
}

func packageRow(p *Package, opts renderOpts) []string {
	status := statusText(p.Status)
	elapsed := fmt.Sprintf("%.2fs", p.Elapsed)
	name := p.Name
	if opts.trimPath != "" {
		name = strings.TrimPrefix(name, opts.trimPath)
	}
	if opts.smallScreen {
		// use only last path segment
		if i := strings.LastIndex(name, "/"); i >= 0 {
			name = name[i+1:]
		}
	}
	if p.Status == StatusNoTest {
		name = name + "\n" + p.NoTestReason
		return []string{status, "0.00s", name, "--", "--", "--", "--"}
	}
	if p.Status == StatusPanic {
		return []string{status, elapsed, name, valOrDash(p.Cover), "--", "--", "--"}
	}
	pass, fail, skip := 0, 0, 0
	for _, t := range p.Tests {
		switch t.Status {
		case StatusPass:
			pass++
		case StatusFail:
			fail++
		case StatusSkip:
			skip++
		}
	}
	return []string{
		status, elapsed, name, valOrDash(p.Cover),
		strconv.Itoa(pass), strconv.Itoa(fail), strconv.Itoa(skip),
	}
}

func valOrDash(s string) string {
	if s == "" {
		return "--"
	}
	return s
}

func statusText(s Status) string {
	name := s.String()
	if !colorsEnabled {
		return name
	}
	switch s {
	case StatusPass:
		return c(name, colorGreen)
	case StatusFail:
		return c(name, colorRed)
	case StatusSkip:
		return c(name, colorYellow)
	case StatusPanic:
		return c(name, colorRed)
	}
	return name
}

func coverVal(s string) float64 {
	if s == "" {
		return 0
	}
	v, _ := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
	return v
}

// ---------------- Table writer ----------------

const tableWidth = 96

func writeTable(w io.Writer, headers []string, rows [][]string, f format, centerHeader bool) {
	// Compute column widths per column (counting visible runes, ignoring ANSI)
	cols := len(headers)
	widths := make([]int, cols)
	for i, h := range headers {
		widths[i] = visibleLen(h)
	}
	for _, r := range rows {
		if r == nil {
			continue
		}
		for i, cell := range r {
			// Multiline cells: consider longest line
			for _, l := range strings.Split(cell, "\n") {
				if v := visibleLen(l); v > widths[i] {
					widths[i] = v
				}
			}
		}
	}
	switch f {
	case formatBasic:
		writeBasicTable(w, headers, rows, widths)
	case formatPlain:
		writePlainTable(w, headers, rows, widths)
	case formatMarkdown:
		writeMarkdownTable(w, headers, rows, widths)
	}
}

func writeBasicTable(w io.Writer, headers []string, rows [][]string, widths []int) {
	// Top border
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	// Header
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+" │")
	}
	fmt.Fprintln(w)
	// Middle
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	// Rows
	for _, r := range rows {
		if r == nil {
			// separator row (blank)
			fmt.Fprint(w, "│")
			for _, wd := range widths {
				fmt.Fprint(w, " "+strings.Repeat(" ", wd)+" │")
			}
			fmt.Fprintln(w)
			continue
		}
		// compute multi-line rows
		maxLines := 1
		cells := make([][]string, len(r))
		for i, cell := range r {
			cells[i] = strings.Split(cell, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, "│")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				aligned := alignCell(headers[i], cell, widths[i])
				fmt.Fprint(w, " "+aligned+" │")
			}
			fmt.Fprintln(w)
		}
	}
	// Bottom border
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}

func writePlainTable(w io.Writer, headers []string, rows [][]string, widths []int) {
	// Header row
	fmt.Fprint(w, " ")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+"  ")
	}
	fmt.Fprintln(w)
	// Separator row (spaces)
	fmt.Fprint(w, " ")
	for _, wd := range widths {
		fmt.Fprint(w, " "+strings.Repeat(" ", wd)+"  ")
	}
	fmt.Fprintln(w)
	// Data rows
	for _, r := range rows {
		if r == nil {
			fmt.Fprint(w, " ")
			for _, wd := range widths {
				fmt.Fprint(w, " "+strings.Repeat(" ", wd)+"  ")
			}
			fmt.Fprintln(w)
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, cell := range r {
			cells[i] = strings.Split(cell, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, " ")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				aligned := alignCell(headers[i], cell, widths[i])
				fmt.Fprint(w, " "+aligned+"  ")
			}
			fmt.Fprintln(w)
		}
	}
}

func writeMarkdownTable(w io.Writer, headers []string, rows [][]string, widths []int) {
	// Header
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+" |")
	}
	fmt.Fprintln(w)
	// Separator
	fmt.Fprint(w, "|")
	for _, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd+2)+"|")
	}
	fmt.Fprintln(w)
	// Rows
	for _, r := range rows {
		if r == nil {
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, cell := range r {
			cells[i] = strings.Split(cell, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, "|")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				aligned := alignCell(headers[i], cell, widths[i])
				fmt.Fprint(w, " "+aligned+" |")
			}
			fmt.Fprintln(w)
		}
	}
}

func alignCell(header, cell string, wd int) string {
	// header "Package" and "Test" are left-aligned; others are centered
	switch strings.TrimSpace(header) {
	case "Package", "Test":
		return padRight(cell, wd)
	}
	return center(cell, wd)
}

func padRight(s string, wd int) string {
	pad := wd - visibleLen(s)
	if pad < 0 {
		pad = 0
	}
	return s + strings.Repeat(" ", pad)
}

func center(s string, wd int) string {
	total := wd - visibleLen(s)
	if total <= 0 {
		return s
	}
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

func visibleLen(s string) int {
	s = ansiRe.ReplaceAllString(s, "")
	return utf8.RuneCountInString(s)
}

// ---------------- Failures / Panics ----------------

func printFailures(w io.Writer, p *Package, opts renderOpts) {
	// Collect failed tests
	var failed []*Test
	for _, n := range p.TestOrder {
		t := p.Tests[n]
		if t.Status == StatusFail {
			failed = append(failed, t)
		}
	}
	if p.HasPanic {
		printPanic(w, p, opts)
		return
	}
	if len(failed) == 0 && p.Status != StatusFail {
		return
	}
	if len(failed) == 0 && p.Status == StatusFail {
		return
	}
	// Print FAIL header box
	title := fmt.Sprintf("  %s  package: %s  ", c("FAIL", colorRed), p.Name)
	printBox(w, title)
	fmt.Fprintln(w)
	for i, t := range failed {
		// Detect --- FAIL line
		var failLine string
		var out []string
		for _, line := range t.Output {
			tr := strings.TrimRight(line, "\n")
			if strings.HasPrefix(tr, "=== RUN") ||
				strings.HasPrefix(tr, "=== PAUSE") ||
				strings.HasPrefix(tr, "=== CONT") ||
				strings.HasPrefix(tr, "=== NAME") {
				continue
			}
			if strings.HasPrefix(tr, "--- FAIL") {
				failLine = tr
				continue
			}
			out = append(out, line)
		}
		fmt.Fprintln(w, failLine)
		fmt.Fprintln(w)
		for _, l := range out {
			fmt.Fprint(w, l)
		}
		fmt.Fprintln(w)
		if i < len(failed)-1 {
			fmt.Fprintln(w, strings.Repeat("─", tableWidth))
			fmt.Fprintln(w, strings.Repeat(" ", tableWidth))
		}
	}
}

func printPanic(w io.Writer, p *Package, opts renderOpts) {
	title := fmt.Sprintf("  %s  package: %s • %s  ", c("PANIC", colorRed), p.Name, p.PanicTest)
	printBox(w, title)
	// Print all test output lines (filtered)
	if p.PanicTest != "" {
		t := p.Tests[p.PanicTest]
		for _, l := range t.Output {
			tr := strings.TrimRight(l, "\n")
			if strings.HasPrefix(tr, "=== RUN") ||
				strings.HasPrefix(tr, "=== PAUSE") ||
				strings.HasPrefix(tr, "=== CONT") ||
				strings.HasPrefix(tr, "=== NAME") ||
				strings.HasPrefix(tr, "--- FAIL") ||
				strings.HasPrefix(tr, "--- PASS") ||
				strings.HasPrefix(tr, "--- SKIP") {
				continue
			}
			line := strings.ReplaceAll(l, "\t", "    ")
			fmt.Fprint(w, line)
		}
	}
	for _, l := range p.PackageOutput {
		tr := strings.TrimSpace(l)
		if tr == "PASS" || tr == "FAIL" || tr == "SKIP" {
			continue
		}
		line := strings.ReplaceAll(l, "\t", "    ")
		fmt.Fprint(w, line)
	}
	fmt.Fprintln(w)
}

func printBox(w io.Writer, content string) {
	width := visibleLen(content)
	top := "┏" + strings.Repeat("━", width) + "┓"
	mid := "┃" + content + "┃"
	bot := "┗" + strings.Repeat("━", width) + "┛"
	if colorsEnabled {
		top = c(top, colorFg103)
		bot = c(bot, colorFg103)
		mid = c("┃", colorFg103) + content + c("┃", colorFg103)
	}
	fmt.Fprintln(w, top)
	fmt.Fprintln(w, mid)
	fmt.Fprintln(w, bot)
}

func printProgressLine(w io.Writer, p *Package) {
	st := statusText(p.Status)
	fmt.Fprintf(w, "[%s]\t%9.2fs\t%s\n", st, p.Elapsed, p.Name)
}

// ---------------- main ----------------

func main() {
	exitCode := run()
	os.Exit(exitCode)
}

const usage = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

func run() int {
	fs := flag.NewFlagSet("tparse", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	help := fs.Bool("h", false, "")
	version := fs.Bool("v", false, "")
	all := fs.Bool("all", false, "")
	passFlag := fs.Bool("pass", false, "")
	skipFlag := fs.Bool("skip", false, "")
	notests := fs.Bool("notests", false, "")
	smallscreen := fs.Bool("smallscreen", false, "")
	slow := fs.Int("slow", 0, "")
	sortBy := fs.String("sort", "name", "")
	nocolor := fs.Bool("nocolor", false, "")
	formatFlag := fs.String("format", "basic", "")
	file := fs.String("file", "", "")
	followFlag := fs.Bool("follow", false, "")
	followOutput := fs.String("follow-output", "", "")
	includeTime := fs.Bool("include-timestamp", false, "")
	progress := fs.Bool("progress", false, "")
	compare := fs.String("compare", "", "")
	trimpath := fs.String("trimpath", "", "")
	_ = compare

	if err := fs.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		fmt.Fprint(os.Stderr, usage)
		return 2
	}
	if *help {
		fmt.Print(usage)
		return 0
	}
	if *version {
		fmt.Println("tparse version: (devel)")
		return 0
	}
	// Validate sort & format
	switch *sortBy {
	case "name", "elapsed", "cover":
	default:
		fmt.Printf("invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", *sortBy)
		return 0
	}
	switch *formatFlag {
	case "basic", "plain", "markdown":
	default:
		fmt.Printf("invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", *formatFlag)
		return 0
	}
	if os.Getenv("NO_COLOR") != "" {
		*nocolor = true
	}
	colorsEnabled = !*nocolor

	// Input source
	var in io.Reader
	if *file != "" {
		f, err := os.Open(*file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		in = f
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			return 1
		}
		in = os.Stdin
	}

	var follow io.Writer
	if *followOutput != "" {
		f, err := os.Create(*followOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		follow = f
	} else if *followFlag {
		follow = os.Stdout
	}

	var fmtVal format
	switch *formatFlag {
	case "basic":
		fmtVal = formatBasic
	case "plain":
		fmtVal = formatPlain
	case "markdown":
		fmtVal = formatMarkdown
	}

	pkgs, order, err := ingest(in, follow, *includeTime)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	opts := renderOpts{
		format:      fmtVal,
		showPass:    *passFlag,
		showSkip:    *skipFlag,
		showAll:     *all,
		showNotest:  *notests,
		smallScreen: *smallscreen,
		slow:        *slow,
		sortBy:      *sortBy,
		trimPath:    *trimpath,
		progress:    *progress,
	}

	render(pkgs, order, os.Stdout, opts)

	// Determine exit code: 1 on any fail
	for _, p := range pkgs {
		if p.Status == StatusFail || p.Status == StatusPanic {
			return 1
		}
	}
	return 0
}
