func writeMarkdown(w io.Writer, headers []string, rows [][]string, widths []int) {
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+" |")
	}
	fmt.Fprintln(w)
	fmt.Fprint(w, "|")
	for _, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd+2)+"|")
	}
	fmt.Fprintln(w)
	for _, r := range rows {
		if r == nil {
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, c := range r {
			cells[i] = strings.Split(c, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, "|")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				fmt.Fprint(w, " "+alignCell(headers[i], cell, widths[i])+" |")
			}
			fmt.Fprintln(w)
		}
	}
}

func alignCell(header, cell string, wd int) string {
	switch strings.TrimSpace(header) {
	case "Package", "Test":
		return padRight(cell, wd)
	}
	return center(cell, wd)
}

func padRight(s string, wd int) string {
	pad := wd - visibleLen(s)
	if pad < 0 {
		pad = 0
	}
	return s + strings.Repeat(" ", pad)
}

func center(s string, wd int) string {
	total := wd - visibleLen(s)
	if total <= 0 {
		return s
	}
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

func visibleLen(s string) int {
	return utf8.RuneCountInString(ansiRe.ReplaceAllString(s, ""))
}

// ---------------- Failure rendering ----------------

func printFailures(w io.Writer, p *Package) {
	var failed []*Test
	for _, tn := range p.TestOrder {
		t := p.Tests[tn]
		if t.Status == StatusFail {
			failed = append(failed, t)
		}
	}
	if len(failed) == 0 {
		return
	}
	// Decide which tests to show. If any failed test has output events,
	// show only those; otherwise show all (as blanks).
	var withOutput []*Test
	for _, t := range failed {
		if len(t.Output) > 0 {
			withOutput = append(withOutput, t)
		}
	}
	shown := failed
	if len(withOutput) > 0 {
		shown = withOutput
	}

	title := "  " + cRed("FAIL") + "  package: " + p.Name + "  "
	printBox(w, title, false)
	fmt.Fprintln(w) // leading blank

	anyHasFailLine := false
	for _, t := range shown {
		if extractFailLine(t) != "" {
			anyHasFailLine = true
			break
		}
	}

	for i, t := range shown {
		failLine, other := splitOutput(t)
		fmt.Fprintln(w, failLine) // FAIL line or "" (which prints blank)
		if len(other) > 0 {
			fmt.Fprintln(w)
			for _, l := range other {
				fmt.Fprint(w, l)
			}
			fmt.Fprintln(w)
		}
		if i < len(shown)-1 && anyHasFailLine {
			fmt.Fprintln(w, strings.Repeat("─", tableWidth))
			fmt.Fprintln(w, strings.Repeat(" ", tableWidth))
		}
	}
}

func extractFailLine(t *Test) string {
	for _, l := range t.Output {
		tr := strings.TrimRight(l, "\n")
		if strings.HasPrefix(tr, "--- FAIL") {
			return tr
		}
	}
	return ""
}

// splitOutput returns the FAIL line (if any) and the other "interesting" output lines.
func splitOutput(t *Test) (string, []string) {
	var failLine string
	var other []string
	for _, l := range t.Output {
		tr := strings.TrimRight(l, "\n")
		if strings.HasPrefix(tr, "=== RUN") ||
			strings.HasPrefix(tr, "=== PAUSE") ||
			strings.HasPrefix(tr, "=== CONT") ||
			strings.HasPrefix(tr, "=== NAME") {
			continue
		}
		if strings.HasPrefix(tr, "--- FAIL") {
			failLine = tr
			continue
		}
		if strings.HasPrefix(tr, "--- PASS") || strings.HasPrefix(tr, "--- SKIP") {
			continue
		}
		other = append(other, l)
	}
	return failLine, other
}

func printPanic(w io.Writer, p *Package) {
	title := "  " + cRed("PANIC") + "  package: " + p.Name
	if p.PanicTest != "" {
		title += " • " + p.PanicTest
	}
	title += "  "
	printBox(w, title, true)

	// Pad output lines to tableWidth
	emit := func(l string) {
		tr := strings.TrimRight(l, "\n")
		pad := tableWidth - visibleLen(tr)
		if pad < 0 {
			pad = 0
		}
		fmt.Fprintln(w, tr+strings.Repeat(" ", pad))
	}

	if p.PanicTest != "" {
		t := p.Tests[p.PanicTest]
		if t != nil {
			for _, l := range t.Output {
				tr := strings.TrimRight(l, "\n")
				if strings.HasPrefix(tr, "=== RUN") ||
					strings.HasPrefix(tr, "=== PAUSE") ||
					strings.HasPrefix(tr, "=== CONT") ||
					strings.HasPrefix(tr, "=== NAME") ||
					strings.HasPrefix(tr, "--- FAIL") ||
					strings.HasPrefix(tr, "--- PASS") ||
					strings.HasPrefix(tr, "--- SKIP") {
					continue
				}
				emit(strings.ReplaceAll(l, "\t", "    "))
			}
		}
	}
	for _, l := range p.PackageOutput {
		emit(strings.ReplaceAll(l, "\t", "    "))
	}
}

func printBox(w io.Writer, content string, padRight bool) {
	width := visibleLen(content)
	pad := ""
	if padRight {
		p := tableWidth - (width + 2) // include box chars
		if p > 0 {
			pad = strings.Repeat(" ", p)
		}
	}
	top := cBox("┏"+strings.Repeat("━", width)+"┓") + pad
	mid := cBox("┃") + content + cBox("┃") + pad
	bot := cBox("┗"+strings.Repeat("━", width)+"┛") + pad
	fmt.Fprintln(w, top)
	fmt.Fprintln(w, mid)
	fmt.Fprintln(w, bot)
}

func printProgressLine(w io.Writer, p *Package) {
	st := statusColored(p.Status)
	fmt.Fprintf(w, "[%s]\t%9.2fs\t%s\n", st, p.Elapsed, p.Name)
}

// ---------------- main ----------------

const usage = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

func main() { os.Exit(run()) }

func run() int {
	fs := flag.NewFlagSet("tparse", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	help := fs.Bool("h", false, "")
	version := fs.Bool("v", false, "")
	all := fs.Bool("all", false, "")
	passFlag := fs.Bool("pass", false, "")
	skipFlag := fs.Bool("skip", false, "")
	notests := fs.Bool("notests", false, "")
	smallscreen := fs.Bool("smallscreen", false, "")
	slow := fs.Int("slow", 0, "")
	sortBy := fs.String("sort", "name", "")
	nocolor := fs.Bool("nocolor", false, "")
	formatFlag := fs.String("format", "basic", "")
	file := fs.String("file", "", "")
	followFlag := fs.Bool("follow", false, "")
	followOutput := fs.String("follow-output", "", "")
	includeTime := fs.Bool("include-timestamp", false, "")
	progress := fs.Bool("progress", false, "")
	_ = fs.String("compare", "", "")
	trimpath := fs.String("trimpath", "", "")

	if err := fs.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		fmt.Fprint(os.Stderr, usage)
		return 2
	}
	if *help {
		fmt.Print(usage)
		return 0
	}
	if *version {
		fmt.Println("tparse version: (devel)")
		return 0
	}
	switch *sortBy {
	case "name", "elapsed", "cover":
	default:
		fmt.Printf("invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", *sortBy)
		return 0
	}
	switch *formatFlag {
	case "basic", "plain", "markdown":
	default:
		fmt.Printf("invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", *formatFlag)
		return 0
	}
	if os.Getenv("NO_COLOR") != "" {
		*nocolor = true
	}
	colorsEnabled = !*nocolor

	var in io.Reader
	if *file != "" {
		f, err := os.Open(*file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		in = f
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			return 1
		}
		in = os.Stdin
	}

	var followW io.Writer
	if *followOutput != "" {
		f, err := os.Create(*followOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		followW = f
	} else if *followFlag {
		followW = os.Stdout
	}

	var fmtVal format
	switch *formatFlag {
	case "plain":
		fmtVal = formatPlain
	case "markdown":
		fmtVal = formatMarkdown
	default:
		fmtVal = formatBasic
	}

	pkgs, order, err := ingest(in, followW, *includeTime)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	opts := renderOpts{
		format:      fmtVal,
		showAll:     *all,
		showPass:    *passFlag,
		showSkip:    *skipFlag,
		showNotest:  *notests,
		smallScreen: *smallscreen,
		slow:        *slow,
		sortBy:      *sortBy,
		trimPath:    *trimpath,
		progress:    *progress,
	}
	// Default is: show no-test rows by default (matching observed behavior)
	if !*notests {
		// We'll flip to true if input only contains no-test packages, or to match default?
		// Actually observed: default shows no-test rows UNLESS other pkgs exist.
		// Simpler: always show them.
		opts.showNotest = true
	}

	render(pkgs, order, os.Stdout, opts)

	for _, p := range pkgs {
		if p.Status == StatusFail || p.Status == StatusPanic {
			return 1
		}
	}
	return 0
}
