	"time"
	"unicode/utf8"
)

// ---------------- ANSI color ----------------

var colorsEnabled = true

func wrap(s, code string) string {
	if !colorsEnabled {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0m"
}

var (
	cRed     = func(s string) string { return wrap(s, "91") }
	cGreen   = func(s string) string { return wrap(s, "92") }
	cYellow  = func(s string) string { return wrap(s, "93") }
	cMagenta = func(s string) string { return wrap(s, "95") }
	cBox     = func(s string) string { return wrap(s, "38;5;103") }
)

// ---------------- Events & models ----------------

type Event struct {
	Time    time.Time
	Action  string
	Package string
	Test    string
	Elapsed float64
	Output  string
}

type Status int

const (
	StatusUnknown Status = iota
	StatusPass
	StatusFail
	StatusSkip
	StatusPanic
	StatusNoTest
)

func (s Status) String() string {
	switch s {
	case StatusPass:
		return "PASS"
	case StatusFail:
		return "FAIL"
	case StatusSkip:
		return "SKIP"
	case StatusPanic:
		return "PANIC"
	case StatusNoTest:
		return "NOTEST"
	}
	return ""
}

type Test struct {
	Name    string
	Package string
	Status  Status
	Elapsed float64
	Output  []string // verbatim outputs including \n
}

type Package struct {
	Name          string
	Status        Status
	Elapsed       float64
	Cover         string
	NoTest        bool
	NoTestReason  string
	HasPanic      bool
	PanicTest     string
	PackageOutput []string
	Tests         map[string]*Test
	TestOrder     []string
}

func newPackage(name string) *Package {
	return &Package{Name: name, Tests: map[string]*Test{}}
}

// ---------------- Ingest ----------------

var (
	coverRe        = regexp.MustCompile(`coverage:\s+([0-9.]+%)\s+of statements`)
	noTestFilesRe  = regexp.MustCompile(`\[no test files\]`)
	noTestsToRunRe = regexp.MustCompile(`\[no tests to run\]`)
)

var errNoParsableEvents = errors.New("no parsable events: Make sure to run go test with -json flag")

func ingest(r io.Reader, followW io.Writer, includeTime bool) (map[string]*Package, []string, error) {
	pkgs := map[string]*Package{}
	var order []string
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024*1024), 10*1024*1024)
	anyEvent := false
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		if len(line) == 0 || line[0] != '{' {
			continue
		}
		var e Event
		if err := json.Unmarshal(line, &e); err != nil {
			continue
		}
		anyEvent = true

		// Follow raw output to writer
		if followW != nil && e.Action == "output" {
			if shouldFollow(e.Output) {
				if includeTime {
					fmt.Fprintf(followW, "%s %s", e.Time.Format(time.RFC3339Nano), e.Output)
				} else {
					fmt.Fprint(followW, e.Output)
				}
			}
		}

		if e.Package == "" {
			continue
		}
		p, ok := pkgs[e.Package]
		if !ok {
			p = newPackage(e.Package)
			pkgs[e.Package] = p
			order = append(order, e.Package)
		}

		switch e.Action {
		case "run":
			if e.Test != "" {
				t := &Test{Name: e.Test, Package: e.Package}
				p.Tests[e.Test] = t
				p.TestOrder = append(p.TestOrder, e.Test)
			}
		case "output":
			if e.Test != "" {
				t, ok := p.Tests[e.Test]
				if !ok {
					t = &Test{Name: e.Test, Package: e.Package}
					p.Tests[e.Test] = t
					p.TestOrder = append(p.TestOrder, e.Test)
				}
				t.Output = append(t.Output, e.Output)
			} else {
				p.PackageOutput = append(p.PackageOutput, e.Output)
				if m := coverRe.FindStringSubmatch(e.Output); m != nil {
					p.Cover = m[1]
				}
				if noTestFilesRe.MatchString(e.Output) {
					p.NoTest = true
					p.NoTestReason = "[no test files]"
				} else if noTestsToRunRe.MatchString(e.Output) {
					p.NoTest = true
					p.NoTestReason = "[no tests to run]"
				}
			}
		case "pass":
			if e.Test != "" {
				if t, ok := p.Tests[e.Test]; ok {
					t.Status = StatusPass
					t.Elapsed = e.Elapsed
				}
			} else {
				if p.Status == StatusUnknown {
					p.Status = StatusPass
				}
				p.Elapsed = e.Elapsed
			}
		case "fail":
			if e.Test != "" {
				if t, ok := p.Tests[e.Test]; ok {
					t.Status = StatusFail
					t.Elapsed = e.Elapsed
				}
			} else {
				if p.Status != StatusPanic {
					p.Status = StatusFail
				}
				p.Elapsed = e.Elapsed
			}
		case "skip":
			if e.Test != "" {
				if t, ok := p.Tests[e.Test]; ok {
					t.Status = StatusSkip
					t.Elapsed = e.Elapsed
				}
			} else {
				if p.Status == StatusUnknown {
					p.Status = StatusPass
				}
				p.Elapsed = e.Elapsed
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, nil, err
	}
	if !anyEvent {
		return nil, nil, errNoParsableEvents
	}

	// Detect panics & set package status
	for _, p := range pkgs {
		for _, tn := range p.TestOrder {
			t := p.Tests[tn]
			for _, l := range t.Output {
				tr := strings.TrimRight(l, "\n")
				if strings.HasPrefix(tr, "panic:") {
					p.HasPanic = true
					p.PanicTest = t.Name
					break
				}
			}
			if p.HasPanic {
				break
			}
		}
		if !p.HasPanic {
			for _, l := range p.PackageOutput {
				tr := strings.TrimRight(l, "\n")
				if strings.HasPrefix(tr, "panic:") {
					p.HasPanic = true
					break
				}
			}
		}
		if p.HasPanic {
			p.Status = StatusPanic
			p.Elapsed = 0
		}
		if p.NoTest && p.Status != StatusPanic {
			p.Status = StatusNoTest
			p.Elapsed = 0
		}
	}

	return pkgs, order, nil
}

func shouldFollow(s string) bool {
	trim := strings.TrimRight(s, "\n")
	if strings.HasPrefix(trim, "=== RUN") ||
		strings.HasPrefix(trim, "=== PAUSE") ||
		strings.HasPrefix(trim, "=== CONT") ||
		strings.HasPrefix(trim, "=== NAME") ||
		strings.HasPrefix(trim, "--- PASS") ||
		strings.HasPrefix(trim, "--- FAIL") ||
		strings.HasPrefix(trim, "--- SKIP") ||
		strings.HasPrefix(trim, "--- BENCH") {
		return false
	}
	t := strings.TrimSpace(trim)
	if t == "PASS" || t == "FAIL" || t == "SKIP" {
		return false
	}
	return true
}

// ---------------- Rendering ----------------

const tableWidth = 96

type format int

const (
	formatBasic format = iota
	formatPlain
	formatMarkdown
)

type renderOpts struct {
	format      format
	showAll     bool
	showPass    bool
	showSkip    bool
	showNotest  bool
	smallScreen bool
	slow        int
	sortBy      string
	trimPath    string
	progress    bool
}

func render(pkgs map[string]*Package, order []string, w io.Writer, opts renderOpts) {
	pkgList := make([]*Package, 0, len(pkgs))
	for _, n := range order {
		pkgList = append(pkgList, pkgs[n])
	}
	switch opts.sortBy {
	case "elapsed":
		sort.SliceStable(pkgList, func(i, j int) bool { return pkgList[i].Elapsed > pkgList[j].Elapsed })
	case "cover":
		sort.SliceStable(pkgList, func(i, j int) bool { return coverVal(pkgList[i].Cover) > coverVal(pkgList[j].Cover) })
	default:
		sort.SliceStable(pkgList, func(i, j int) bool { return pkgList[i].Name < pkgList[j].Name })
	}

	if opts.progress {
		for _, p := range pkgList {
			printProgressLine(w, p)
		}
	}

	// Tests table
	var testRows [][]string
	showTable := opts.showAll || opts.showPass || opts.showSkip
	if showTable {
		for pi, p := range pkgList {
			var tests []*Test
			for _, tn := range p.TestOrder {
				t := p.Tests[tn]
				if t.Status == StatusPass && (opts.showAll || opts.showPass) {
					tests = append(tests, t)
				} else if t.Status == StatusSkip && (opts.showAll || opts.showSkip) {
					tests = append(tests, t)
				}
			}
			// within a package sort by elapsed desc
			sort.SliceStable(tests, func(i, j int) bool { return tests[i].Elapsed > tests[j].Elapsed })
			for _, t := range tests {
				testRows = append(testRows, testRow(t, opts))
			}
			if len(tests) > 0 && pi < len(pkgList)-1 {
				testRows = append(testRows, nil)
			}
		}
		for len(testRows) > 0 && testRows[len(testRows)-1] == nil {
			testRows = testRows[:len(testRows)-1]
		}
		if opts.slow > 0 && len(testRows) > 0 {
			flat := make([][]string, 0, len(testRows))
			for _, r := range testRows {
				if r != nil {
					flat = append(flat, r)
				}
			}
			sort.SliceStable(flat, func(i, j int) bool {
				ei, _ := strconv.ParseFloat(flat[i][1], 64)
				ej, _ := strconv.ParseFloat(flat[j][1], 64)
				return ei > ej
			})
			if len(flat) > opts.slow {
				flat = flat[:opts.slow]
			}
			testRows = flat
		}
		if len(testRows) > 0 {
			headers := []string{"Status", "Elapsed", "Test", "Package"}
			writeTable(w, headers, testRows, opts.format)
		}
	}

	// Failure / panic sections
	for _, p := range pkgList {
		if p.HasPanic {
			printPanic(w, p)
		} else {
			printFailures(w, p)
		}
	}

	// Summary table
	var rows [][]string
	for _, p := range pkgList {
		if p.Status == StatusNoTest && !opts.showNotest {
			continue
		}
		rows = append(rows, packageRow(p, opts))
	}
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	writeTable(w, headers, rows, opts.format)
}

func coverVal(s string) float64 {
	if s == "" {
		return 0
	}
	v, _ := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
	return v
}

func testRow(t *Test, opts renderOpts) []string {
	name := t.Name
	pkg := t.Package
	if opts.trimPath != "" {
		pkg = strings.TrimPrefix(pkg, opts.trimPath)
	}
	if opts.smallScreen {
		if i := strings.LastIndex(pkg, "/"); i >= 0 {
			pkg = pkg[i+1:]
		}
		// Break test name on / for small screen (split at first /)
		if i := strings.Index(name, "/"); i >= 0 {
			name = name[:i] + "\n /" + name[i+1:]
		}
	}
	return []string{statusColored(t.Status), fmt.Sprintf("%.2f", t.Elapsed), name, pkg}
}

func packageRow(p *Package, opts renderOpts) []string {
	status := statusColored(p.Status)
	elapsed := fmt.Sprintf("%.2fs", p.Elapsed)
	name := p.Name
	if opts.trimPath != "" {
		name = strings.TrimPrefix(name, opts.trimPath)
	}
	if opts.smallScreen {
		if i := strings.LastIndex(name, "/"); i >= 0 {
			name = name[i+1:]
		}
	}
	if p.Status == StatusNoTest {
		return []string{status, "0.00s", name + "\n" + p.NoTestReason, "--", "--", "--", "--"}
	}
	if p.Status == StatusPanic {
		return []string{status, "0.00s", name, "--", "--", "--", "--"}
	}
	pass, fail, skip := 0, 0, 0
	for _, t := range p.Tests {
		switch t.Status {
		case StatusPass:
			pass++
		case StatusFail:
			fail++
		case StatusSkip:
			skip++
		}
	}
	cov := "--"
	if p.Cover != "" {
		cov = colorizeCover(p.Cover)
	}
	return []string{status, elapsed, name, cov, strconv.Itoa(pass), strconv.Itoa(fail), strconv.Itoa(skip)}
}

func statusColored(s Status) string {
	name := s.String()
	if !colorsEnabled {
		return name
	}
	switch s {
	case StatusPass:
		return cGreen(name)
	case StatusFail:
		return cRed(name)
	case StatusSkip:
		return cYellow(name)
	case StatusPanic:
		return cRed(name)
	case StatusNoTest:
		return name
	}
	return name
}

func colorizeCover(s string) string {
	if !colorsEnabled {
		return s
	}
	v, _ := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
	switch {
	case v <= 50.0:
		return cRed(s)
	case v < 80.0:
		return cYellow(s)
	default:
		return cGreen(s)
	}
}

// ---------------- Tables ----------------

func writeTable(w io.Writer, headers []string, rows [][]string, f format) {
	cols := len(headers)
	widths := make([]int, cols)
	for i, h := range headers {
		widths[i] = visibleLen(h)
	}
	for _, r := range rows {
		if r == nil {
			continue
		}
		for i, c := range r {
			for _, l := range strings.Split(c, "\n") {
				if v := visibleLen(l); v > widths[i] {
					widths[i] = v
				}
			}
		}
	}
	switch f {
	case formatPlain:
		writePlain(w, headers, rows, widths)
	case formatMarkdown:
		writeMarkdown(w, headers, rows, widths)
	default:
		writeBasic(w, headers, rows, widths)
	}
}

func writeBasic(w io.Writer, headers []string, rows [][]string, widths []int) {
	// top
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	// header
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+" │")
	}
	fmt.Fprintln(w)
	// mid
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	for _, r := range rows {
		if r == nil {
			fmt.Fprint(w, "│")
			for _, wd := range widths {
				fmt.Fprint(w, " "+strings.Repeat(" ", wd)+" │")
			}
			fmt.Fprintln(w)
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, c := range r {
			cells[i] = strings.Split(c, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, "│")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				fmt.Fprint(w, " "+alignCell(headers[i], cell, widths[i])+" │")
			}
			fmt.Fprintln(w)
		}
	}
	// bottom
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd+2))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}

func writePlain(w io.Writer, headers []string, rows [][]string, widths []int) {
	fmt.Fprint(w, " ")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+"  ")
	}
	fmt.Fprintln(w)
	fmt.Fprint(w, " ")
	for _, wd := range widths {
		fmt.Fprint(w, " "+strings.Repeat(" ", wd)+"  ")
	}
	fmt.Fprintln(w)
	for _, r := range rows {
		if r == nil {
			fmt.Fprint(w, " ")
			for _, wd := range widths {
				fmt.Fprint(w, " "+strings.Repeat(" ", wd)+"  ")
			}
			fmt.Fprintln(w)
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, c := range r {
			cells[i] = strings.Split(c, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, " ")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				fmt.Fprint(w, " "+alignCell(headers[i], cell, widths[i])+"  ")
			}
			fmt.Fprintln(w)
		}
	}
}

func writeMarkdown(w io.Writer, headers []string, rows [][]string, widths []int) {
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, " "+center(h, widths[i])+" |")
	}
	fmt.Fprintln(w)
	fmt.Fprint(w, "|")
	for _, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd+2)+"|")
	}
	fmt.Fprintln(w)
	for _, r := range rows {
		if r == nil {
			continue
		}
		maxLines := 1
		cells := make([][]string, len(r))
		for i, c := range r {
			cells[i] = strings.Split(c, "\n")
			if len(cells[i]) > maxLines {
				maxLines = len(cells[i])
			}
		}
		for ln := 0; ln < maxLines; ln++ {
			fmt.Fprint(w, "|")
			for i := range r {
				var cell string
				if ln < len(cells[i]) {
					cell = cells[i][ln]
				}
				fmt.Fprint(w, " "+alignCell(headers[i], cell, widths[i])+" |")
			}
			fmt.Fprintln(w)
		}
	}
}

func alignCell(header, cell string, wd int) string {
	switch strings.TrimSpace(header) {
	case "Package", "Test":
		return padRight(cell, wd)
	}
	return center(cell, wd)
}

func padRight(s string, wd int) string {
	pad := wd - visibleLen(s)
	if pad < 0 {
		pad = 0
	}
	return s + strings.Repeat(" ", pad)
}

func center(s string, wd int) string {
	total := wd - visibleLen(s)
	if total <= 0 {
		return s
	}
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

func visibleLen(s string) int {
	return utf8.RuneCountInString(ansiRe.ReplaceAllString(s, ""))
}

// ---------------- Failure rendering ----------------

func printFailures(w io.Writer, p *Package) {
	var failed []*Test
	for _, tn := range p.TestOrder {
		t := p.Tests[tn]
		if t.Status == StatusFail {
			failed = append(failed, t)
		}
	}
	if len(failed) == 0 {
		return
	}
	// Decide which tests to show. If any failed test has output events,
	// show only those; otherwise show all (as blanks).
	var withOutput []*Test
	for _, t := range failed {
		if len(t.Output) > 0 {
			withOutput = append(withOutput, t)
		}
	}
	shown := failed
	if len(withOutput) > 0 {
		shown = withOutput
	}

	title := "  " + cRed("FAIL") + "  package: " + p.Name + "  "
	printBox(w, title, false)
	fmt.Fprintln(w) // leading blank

	anyHasFailLine := false
	for _, t := range shown {
		if extractFailLine(t) != "" {
			anyHasFailLine = true
			break
		}
	}

	for i, t := range shown {
		failLine, other := splitOutput(t)
		fmt.Fprintln(w, failLine) // FAIL line or "" (which prints blank)
		if len(other) > 0 {
			fmt.Fprintln(w)
			for _, l := range other {
				fmt.Fprint(w, l)
			}
			fmt.Fprintln(w)
		}
		if i < len(shown)-1 && anyHasFailLine {
			fmt.Fprintln(w, strings.Repeat("─", tableWidth))
			fmt.Fprintln(w, strings.Repeat(" ", tableWidth))
		}
	}
}

func extractFailLine(t *Test) string {
	for _, l := range t.Output {
		tr := strings.TrimRight(l, "\n")
		if strings.HasPrefix(tr, "--- FAIL") {
			return tr
		}
	}
	return ""
}

// splitOutput returns the FAIL line (if any) and the other "interesting" output lines.
func splitOutput(t *Test) (string, []string) {
	var failLine string
	var other []string
	for _, l := range t.Output {
		tr := strings.TrimRight(l, "\n")
		if strings.HasPrefix(tr, "=== RUN") ||
			strings.HasPrefix(tr, "=== PAUSE") ||
			strings.HasPrefix(tr, "=== CONT") ||
			strings.HasPrefix(tr, "=== NAME") {
			continue
		}
		if strings.HasPrefix(tr, "--- FAIL") {
			failLine = tr
			continue
		}
		if strings.HasPrefix(tr, "--- PASS") || strings.HasPrefix(tr, "--- SKIP") {
			continue
		}
		other = append(other, l)
	}
	return failLine, other
}

func printPanic(w io.Writer, p *Package) {
	title := "  " + cRed("PANIC") + "  package: " + p.Name
	if p.PanicTest != "" {
		title += " • " + p.PanicTest
	}
	title += "  "
	printBox(w, title, true)

	// Pad output lines to tableWidth
	emit := func(l string) {
		tr := strings.TrimRight(l, "\n")
		pad := tableWidth - visibleLen(tr)
		if pad < 0 {
			pad = 0
		}
		fmt.Fprintln(w, tr+strings.Repeat(" ", pad))
	}

	if p.PanicTest != "" {
		t := p.Tests[p.PanicTest]
		if t != nil {
			for _, l := range t.Output {
				tr := strings.TrimRight(l, "\n")
				if strings.HasPrefix(tr, "=== RUN") ||
					strings.HasPrefix(tr, "=== PAUSE") ||
					strings.HasPrefix(tr, "=== CONT") ||
					strings.HasPrefix(tr, "=== NAME") ||
					strings.HasPrefix(tr, "--- FAIL") ||
					strings.HasPrefix(tr, "--- PASS") ||
					strings.HasPrefix(tr, "--- SKIP") {
					continue
				}
				emit(strings.ReplaceAll(l, "\t", "    "))
			}
		}
	}
	for _, l := range p.PackageOutput {
		emit(strings.ReplaceAll(l, "\t", "    "))
	}
}

func printBox(w io.Writer, content string, padRight bool) {
	width := visibleLen(content)
	pad := ""
	if padRight {
		p := tableWidth - (width + 2) // include box chars
		if p > 0 {
			pad = strings.Repeat(" ", p)
		}
	}
	top := cBox("┏"+strings.Repeat("━", width)+"┓") + pad
	mid := cBox("┃") + content + cBox("┃") + pad
	bot := cBox("┗"+strings.Repeat("━", width)+"┛") + pad
	fmt.Fprintln(w, top)
	fmt.Fprintln(w, mid)
	fmt.Fprintln(w, bot)
}

func printProgressLine(w io.Writer, p *Package) {
	st := statusColored(p.Status)
	fmt.Fprintf(w, "[%s]\t%9.2fs\t%s\n", st, p.Elapsed, p.Name)
}

// ---------------- main ----------------

const usage = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

func main() { os.Exit(run()) }

func run() int {
	fs := flag.NewFlagSet("tparse", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	help := fs.Bool("h", false, "")
	version := fs.Bool("v", false, "")
	all := fs.Bool("all", false, "")
	passFlag := fs.Bool("pass", false, "")
	skipFlag := fs.Bool("skip", false, "")
	notests := fs.Bool("notests", false, "")
	smallscreen := fs.Bool("smallscreen", false, "")
	slow := fs.Int("slow", 0, "")
	sortBy := fs.String("sort", "name", "")
	nocolor := fs.Bool("nocolor", false, "")
	formatFlag := fs.String("format", "basic", "")
	file := fs.String("file", "", "")
	followFlag := fs.Bool("follow", false, "")
	followOutput := fs.String("follow-output", "", "")
	includeTime := fs.Bool("include-timestamp", false, "")
	progress := fs.Bool("progress", false, "")
	_ = fs.String("compare", "", "")
	trimpath := fs.String("trimpath", "", "")

	if err := fs.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		fmt.Fprint(os.Stderr, usage)
		return 2
	}
	if *help {
		fmt.Print(usage)
		return 0
	}
	if *version {
		fmt.Println("tparse version: (devel)")
		return 0
	}
	switch *sortBy {
	case "name", "elapsed", "cover":
	default:
		fmt.Printf("invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", *sortBy)
		return 0
	}
	switch *formatFlag {
	case "basic", "plain", "markdown":
	default:
		fmt.Printf("invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", *formatFlag)
		return 0
	}
	if os.Getenv("NO_COLOR") != "" {
		*nocolor = true
	}
	colorsEnabled = !*nocolor

	var in io.Reader
	if *file != "" {
		f, err := os.Open(*file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		in = f
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			return 1
		}
		in = os.Stdin
	}

	var followW io.Writer
	if *followOutput != "" {
		f, err := os.Create(*followOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			return 1
		}
		defer f.Close()
		followW = f
	} else if *followFlag {
		followW = os.Stdout
	}

	var fmtVal format
	switch *formatFlag {
	case "plain":
		fmtVal = formatPlain
	case "markdown":
		fmtVal = formatMarkdown
	default:
		fmtVal = formatBasic
	}

	pkgs, order, err := ingest(in, followW, *includeTime)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	opts := renderOpts{
		format:      fmtVal,
		showAll:     *all,
		showPass:    *passFlag,
		showSkip:    *skipFlag,
		showNotest:  *notests,
		smallScreen: *smallscreen,
		slow:        *slow,
		sortBy:      *sortBy,
		trimPath:    *trimpath,
		progress:    *progress,
	}
	// Default is: show no-test rows by default (matching observed behavior)
	if !*notests {
		// We'll flip to true if input only contains no-test packages, or to match default?
		// Actually observed: default shows no-test rows UNLESS other pkgs exist.
		// Simpler: always show them.
		opts.showNotest = true
	}

	render(pkgs, order, os.Stdout, opts)

	for _, p := range pkgs {
		if p.Status == StatusFail || p.Status == StatusPanic {
			return 1
		}
	}
	return 0
}
